/** Exact N06 originals. Journal writes require live authority plus private physical
 * Registered proofs; recovery and lifecycle readers cannot manufacture completion. */
public final class TaskCandidateAssemblyStageJournal {
 static final String PREPARE="task.candidate_assembly.stage.prepare.v1",DISPATCH="task.candidate_assembly.stage.dispatch.v1",PRODUCE="task.candidate_assembly.stage.produced.v1",COMMIT="task.candidate_assembly.stage.committed.v1";
 static final String MANIFEST=org.apache.commons.codec.digest.DigestUtils.sha256Hex("N06_STAGE_V1:prepare:dispatch:four-physical-originals:commit:no-document-save:no-N07");
 private final JdbcTemplate db;private final TaskRunActivityJournal journal;private final TaskSourceVerifierSchema json;private final TaskRunWorkflowProtocolBinding protocols;
 private final JsonMapper reader=JsonMapper.builder().propertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).enable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES).enable(DeserializationFeature.FAIL_ON_MISSING_CREATOR_PROPERTIES).build();
 public TaskCandidateAssemblyStageJournal(DataSource data,PermissionSchema permissions,TaskSourceVerifierSchema json,TaskRunWorkflowProtocolBinding protocols){db=new JdbcTemplate(data);db.setQueryTimeout(5);journal=new TaskRunActivityJournal(db,permissions);this.json=json;this.protocols=protocols;}
 PreparedV1 prepared(TaskCandidateAssemblyAuthority.Verified i)throws Exception{var p=i.production();return new PreparedV1("1.0.0",p.runId(),i.stepId(),i.inputSha256(),i.graphId(),i.graphSha256(),json.hash(Map.of("schema_version","1.0.0","kind","TASK_REQUIRED_STAGE","tenant_id",p.tenantId(),"project_id",p.projectId(),"run_id",p.runId(),"graph_id",i.graphId(),"graph_sha256",i.graphSha256(),"stage_kind","N06")));}
 Optional<PreparedV1> preparedOriginal(EnterpriseAccess.Admission a,WorkflowProtocol.Reference ref)throws Exception{var saved=read(a,ref,PREPARE,action(ref));if(saved.isEmpty())return Optional.empty();var value=reader.treeToValue(saved.get().required("prepared"),PreparedV1.class);value.require(ref);same(value.inputSha256(),json.hash(saved.get().required("input")));protocols.assemblies().requireAccepted(a,ref.runId()).requireUnchanged();return Optional.of(value);}
 PreparedV1 prepare(WorkflowProtocol.Reference ref,TaskCandidateAssemblyAuthority.Verified i)throws Exception{current(ref,i);var value=prepared(i);value.require(ref);write(i.production().admission(),ref,PREPARE,i.actionId(),json.tree(Map.of("prepared",value,"input",i.input())));i.requireUnchanged();return value;}
 void dispatch(WorkflowProtocol.Reference ref,CommandV1 command,TaskCandidateAssemblyAuthority.Verified i)throws Exception{current(ref,i);same(prepared(i),command.prepared());same(json.tree(command.prepared()),read(i.production().admission(),ref,PREPARE,i.actionId()).orElseThrow().required("prepared"));write(i.production().admission(),ref,DISPATCH,i.actionId(),json.tree(command));i.requireUnchanged();}
 ProducedV1 produced(WorkflowProtocol.Reference ref,CommandV1 command,TaskCandidateAssemblyAuthority.Verified i,List<TaskCandidateAssemblyObjectLedger.Registered> originals,boolean save)throws Exception{
  current(ref,i);if(!i.hasCommittedCheck())bad();same(prepared(i),command.prepared());same(json.tree(command),read(i.production().admission(),ref,DISPATCH,i.actionId()).orElseThrow());var artifacts=new ArrayList<ArtifactV1>();
  for(var a:originals.stream().sorted(java.util.Comparator.comparingInt(a->TaskCandidateAssemblyStageProtocolV1.KINDS.indexOf(a.kind()))).toList()){a.requireUnchanged();artifacts.add(new ArtifactV1(a.kind(),a.artifactId(),a.reference().sha256(),a.reference().objectVersion(),a.receiptSha256()));}
  var produced=new ProducedV1("1.0.0",command,artifacts,i.ready(),i.blockers(),false,false);var prior=read(i.production().admission(),ref,PRODUCE,i.actionId());
  if(save)write(i.production().admission(),ref,PRODUCE,i.actionId(),json.tree(produced));else if(prior.isPresent())same(json.tree(produced),prior.get());
  i.requireUnchanged();return produced;
 }
 ProducedV1 recovered(Original original,TaskCandidateAssemblyOriginalReader.Verified family)throws Exception{
  original.requireUnchanged();family.requireUnchanged();var artifacts=new ArrayList<ArtifactV1>();for(var a:family.artifacts().stream().sorted(java.util.Comparator.comparingInt(a->TaskCandidateAssemblyStageProtocolV1.KINDS.indexOf(a.kind()))).toList())artifacts.add(new ArtifactV1(a.kind(),a.artifactId(),a.reference().sha256(),a.reference().objectVersion(),a.receiptSha256()));var value=new ProducedV1("1.0.0",original.command(),artifacts,family.ready(),family.blockers(),false,false);var saved=read(original.admission(),original.reference(),PRODUCE,original.actionId(),original.human);if(saved.isPresent())same(json.tree(value),saved.get());family.requireUnchanged();original.requireUnchanged();return value;
 }
 CommitV1 commit(WorkflowProtocol.Reference ref,ProducedV1 expected,TaskCandidateAssemblyAuthority.Verified i,List<TaskCandidateAssemblyObjectLedger.Registered> originals)throws Exception{
  var actual=produced(ref,expected.command(),i,originals,true);same(expected,actual);var p=i.production();same(json.tree(expected),read(p.admission(),ref,PRODUCE,i.actionId()).orElseThrow());var body=body(ref,expected);var receipt=new CommitV1("1.0.0",expected,derived(i.actionId(),COMMIT),json.hash(body));write(p.admission(),ref,COMMIT,i.actionId(),json.tree(Map.of("body",body,"receipt",receipt)));i.requireUnchanged();return receipt;
 }
 /** Transaction-scoped historical stage authority. It grants read-only original
  * retrieval, never new production, current node rights, or document adoption. */
 Original original(EnterpriseAccess.Admission admission,WorkflowProtocol.Reference ref,CommandV1 expected)throws Exception{
  var found=command(admission,ref).orElseThrow(()->new TenantAccessException(com.ruoyi.medical.contracts.ErrorCode.DEPENDENCY_UNAVAILABLE));same(expected,found);var value=read(admission,ref,PREPARE,action(ref)).orElseThrow();same(json.tree(found.prepared()),value.required("prepared"));same(found.prepared().inputSha256(),json.hash(value.required("input")));protocols.assemblies().requireAccepted(admission,ref.runId()).requireUnchanged();return new Original(admission,ref,found,value.required("input"));
 }
 Original originalResume(TaskRunAssemblyResumeOriginalAuthority.Source source)throws Exception {
  source.requireUnchanged();var a=source.admission();var row=one(db.queryForList("SELECT reference_json FROM task_run_workflow_launch WHERE tenant_id=? AND run_id=? LIMIT 2 FOR UPDATE",a.context().tenant_id(),source.originalRunId()));
  var ref=reader.treeToValue(json.read(text(row,"reference_json")),WorkflowProtocol.Reference.class);source.requireOriginal(a,ref.runId());
  var command=command(a,ref).orElseThrow(()->new TenantAccessException(com.ruoyi.medical.contracts.ErrorCode.STEP_NOT_READY));var original=original(a,ref,command);
  return new Original(a,ref,command,original.input(),null,source);
 }
 Original originalHuman(TaskCandidateAssemblyHumanReadAuthority.Verified human,WorkflowProtocol.Reference ref,CommandV1 expected)throws Exception{
  var a=human.admission();human.require(a);same(ref.runId(),human.runId());same(ref.projectId(),human.projectId());var found=commandHuman(human,ref).orElseThrow();same(expected,found);var value=read(a,ref,PREPARE,action(ref),human).orElseThrow();same(json.tree(found.prepared()),value.required("prepared"));same(found.prepared().inputSha256(),json.hash(value.required("input")));protocols.assemblies().requireAssemblyOriginal(human).requireUnchanged();return new Original(a,ref,found,value.required("input"),human);
 }
 Optional<CommandV1> commandHuman(TaskCandidateAssemblyHumanReadAuthority.Verified human,WorkflowProtocol.Reference ref)throws Exception{human.require(human.admission());var n=read(human.admission(),ref,DISPATCH,action(ref),human);return n.isEmpty()?Optional.empty():Optional.of(reader.treeToValue(n.get(),CommandV1.class));}
 Optional<CommitV1> committed(Original original)throws Exception{original.requireUnchanged();return committed(original.admission(),original.reference(),original.command(),original.human);}
 public final class Original {
  private final TaskRunAssemblyResumeOriginalAuthority.Source resumeSource;private final TaskCandidateAssemblyHumanReadAuthority.Verified human;private final EnterpriseAccess.Admission admission;private final WorkflowProtocol.Reference reference;private final CommandV1 command;private final JsonNode input;private final Thread thread=Thread.currentThread();private final TenantScope scope=TenantScope.requireCurrent();private final Map<Object,Object> resources=Map.copyOf(org.springframework.transaction.support.TransactionSynchronizationManager.getResourceMap());private boolean ended;
  private Original(EnterpriseAccess.Admission a,WorkflowProtocol.Reference r,CommandV1 c,JsonNode i){this(a,r,c,i,null);}
  private Original(EnterpriseAccess.Admission a,WorkflowProtocol.Reference r,CommandV1 c,JsonNode i,TaskCandidateAssemblyHumanReadAuthority.Verified human){this(a,r,c,i,human,null);}
  private Original(EnterpriseAccess.Admission a,WorkflowProtocol.Reference r,CommandV1 c,JsonNode i,TaskCandidateAssemblyHumanReadAuthority.Verified human,TaskRunAssemblyResumeOriginalAuthority.Source resumeSource){this.resumeSource=resumeSource;this.human=human;admission=a;reference=r;command=c;input=i.deepCopy();if(resources.isEmpty()||!org.springframework.transaction.support.TransactionSynchronizationManager.isSynchronizationActive())bad();org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){public void afterCompletion(int status){ended=true;}});}
  public void requireUnchanged()throws Exception{var current=org.springframework.transaction.support.TransactionSynchronizationManager.getResourceMap();if(ended||thread!=Thread.currentThread()||scope!=TenantScope.requireCurrent()||resources.size()!=current.size()||resources.entrySet().stream().anyMatch(e->current.get(e.getKey())!=e.getValue()))bad();if(resumeSource!=null)resumeSource.requireOriginal(admission,reference.runId());if(human!=null)human.require(admission);same(command,(human==null?TaskCandidateAssemblyStageJournal.this.command(admission,reference):commandHuman(human,reference)).orElseThrow());var value=read(admission,reference,PREPARE,action(reference),human).orElseThrow();same(input,value.required("input"));same(json.tree(command.prepared()),value.required("prepared"));if(human==null)protocols.assemblies().requireAccepted(admission,reference.runId()).requireUnchanged();else protocols.assemblies().requireAssemblyOriginal(human).requireUnchanged();}
  public TaskRunAssemblyResumeOriginalAuthority.Source resumeSource(){if(resumeSource==null)bad();return resumeSource;}
  public EnterpriseAccess.Admission admission(){return admission;}public WorkflowProtocol.Reference reference(){return reference;}public CommandV1 command(){return command;}public JsonNode input(){return input.deepCopy();}public String tenantId(){return reference.tenantId();}public String projectId(){return reference.projectId();}public String runId(){return reference.runId();}public String actorId(){return human==null?admission.actorId():human.originalActorId();}public String taskId(){return input.required("task_id").asText();}public String stepId(){return command.prepared().stepId();}public String actionId(){return action(reference);}public String inputSha256(){return command.prepared().inputSha256();}
 }
 Optional<CommandV1> command(EnterpriseAccess.Admission a,WorkflowProtocol.Reference ref)throws Exception{return read(a,ref,DISPATCH,action(ref)).map(n->{try{return reader.treeToValue(n,CommandV1.class);}catch(Exception e){throw new IllegalArgumentException(e);}});}
 Optional<CommitV1> committed(EnterpriseAccess.Admission a,WorkflowProtocol.Reference ref,CommandV1 expected)throws Exception{return committed(a,ref,expected,null);}
 private Optional<CommitV1> committed(EnterpriseAccess.Admission a,WorkflowProtocol.Reference ref,CommandV1 expected,TaskCandidateAssemblyHumanReadAuthority.Verified human)throws Exception{var saved=read(a,ref,COMMIT,action(ref),human);if(saved.isEmpty())return Optional.empty();var n=saved.get();if(n.size()!=2||!n.has("body")||!n.has("receipt"))bad();var c=reader.treeToValue(n.required("receipt"),CommitV1.class);c.require(ref);same(expected,c.produced().command());same(derived(action(ref),COMMIT),c.receiptId());same(json.hash(n.required("body")),c.receiptSha256());same(body(ref,c.produced()),n.required("body"));same(json.tree(c.produced()),read(a,ref,PRODUCE,action(ref),human).orElseThrow());return Optional.of(c);}
 /** Lifecycle consumes only immutable registered objects and existing COMMIT. */
 Optional<CommitV1> lifecycle(TaskRunLifecycleAuthority.Proof proof)throws Exception{proof.require(proof.operation());var ref=proof.reference();var cmd=command(proof.admission(),ref);if(cmd.isEmpty())return Optional.empty();var result=committed(proof.admission(),ref,cmd.get());if(result.isEmpty())return result;var c=result.get();var fixedInput=read(proof.admission(),ref,PREPARE,action(ref)).orElseThrow().required("input");same(cmd.get().prepared().inputSha256(),json.hash(fixedInput));same(proof.graph().graphId(),cmd.get().prepared().graphId());same(proof.graph().graphSha256(),cmd.get().prepared().graphSha256());protocols.assemblies().requireAccepted(proof.admission(),ref.runId()).requireUnchanged();
  for(var artifact:c.produced().artifacts()){
   var row=one(db.queryForList("SELECT * FROM task_candidate_assembly_object WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND artifact_id=? LIMIT 2 FOR UPDATE",ref.tenantId(),ref.projectId(),ref.runId(),cmd.get().prepared().stepId(),artifact.artifactId()));var receipt=json.read(text(row,"receipt_json"));TaskCandidateAssemblyContracts.validate(fixedInput,artifact.kind(),json.read(text(row,"canonical_payload")));var binding=one(db.queryForList("SELECT schema_ref,schema_document_sha256,resource_kind,resource_id FROM artifact_content_binding WHERE tenant_id=? AND artifact_id=? LIMIT 2 FOR UPDATE",ref.tenantId(),artifact.artifactId()));same(TaskCandidateAssemblyObjectLedger.REF,text(binding,"schema_ref"));same(TaskCandidateAssemblyContracts.outerSha(),text(binding,"schema_document_sha256"));same("TASK",text(binding,"resource_kind"));same(fixedInput.required("task_id").asText(),text(binding,"resource_id"));same(artifact.receiptSha256(),json.hash(receipt));same(artifact.receiptSha256(),text(row,"receipt_sha256"));same(artifact.payloadSha256(),com.ruoyi.medical.contracts.WireValues.sha256(text(row,"canonical_payload").getBytes(java.nio.charset.StandardCharsets.UTF_8)));same(artifact.kind(),text(row,"kind"));same(artifact.payloadSha256(),text(row,"payload_sha256"));same(artifact.objectVersion(),text(row,"object_version"));same(cmd.get().prepared().inputSha256(),receipt.required("input_sha256").asText());same(c.produced().ready(),receipt.required("ready").asBoolean());same(json.tree(c.produced().blockers()),receipt.required("blockers"));if(receipt.required("document_saved").asBoolean()||receipt.required("n07_complete").asBoolean())bad();same(proof.admission().actorId(),text(row,"created_by"));
   var stored=one(db.queryForList("SELECT object_ref,sha256,artifact_kind FROM artifact WHERE tenant_id=? AND project_id=? AND run_id=? AND artifact_id=? LIMIT 2 FOR UPDATE",ref.tenantId(),ref.projectId(),ref.runId(),artifact.artifactId()));same(artifact.payloadSha256(),text(stored,"sha256"));same(artifact.kind(),text(stored,"artifact_kind"));StoredObjectReferences.decode(text(stored,"object_ref"),reader.treeToValue(receipt.required("object_ref"),com.ruoyi.medical.contracts.InterfaceProtocol.ObjectRef.class));
   var audit=one(db.queryForList("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND audit_id=? AND subject_id=? AND action='task.candidate_assembly.object.registered' AND result='SUCCESS' LIMIT 2",ref.tenantId(),ref.projectId(),text(row,"audit_id"),proof.admission().actorId()));same(receipt,json.read(text(audit,"resource_ref")));var event=one(db.queryForList("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND event_type='task.candidate_assembly.object.registered' LIMIT 2",ref.tenantId(),text(row,"event_id")));same(receipt,json.read(text(event,"payload")));
  }
  var check=one(db.queryForList("SELECT * FROM check_run WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND target_kind='CANDIDATE_SET' LIMIT 2 FOR UPDATE",ref.tenantId(),ref.projectId(),ref.runId(),cmd.get().prepared().stepId()));var checkReceipt=json.read(text(check,"result_ref"));var report=c.produced().artifacts().stream().filter(a->"CROSS_FILE_CHECK_REPORT".equals(a.kind())).findFirst().orElseThrow();same(report.artifactId(),text(check,"target_revision"));same(ref.runId(),text(check,"target_id"));same(report.artifactId(),text(check,"coverage_artifact_id"));same(report.artifactId(),text(check,"findings_artifact_id"));same(cmd.get().prepared().inputSha256(),text(check,"input_sha256"));same(c.produced().ready()?"SUCCEEDED":"WAITING_INPUT",text(check,"status"));same(proof.admission().actorId(),text(check,"created_by"));same(text(check,"check_id"),checkReceipt.required("check_id").asText());same(report.receiptSha256(),checkReceipt.required("report_receipt_sha256").asText());same(report.payloadSha256(),checkReceipt.required("report_sha256").asText());same(json.tree(c.produced().blockers()),checkReceipt.required("blockers"));if(checkReceipt.required("document_saved").asBoolean()||checkReceipt.required("n07_complete").asBoolean()||checkReceipt.required("professional_approval").asBoolean())bad();
  var checkAudit=one(db.queryForList("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND audit_id=? AND subject_id=? AND action='task.candidate_assembly.check.committed' AND result='SUCCESS' LIMIT 2",ref.tenantId(),ref.projectId(),checkReceipt.required("audit_id").asText(),proof.admission().actorId()));same(checkReceipt,json.read(text(checkAudit,"resource_ref")));var checkEvent=one(db.queryForList("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND aggregate_id=? AND event_type='task.candidate_assembly.check.committed' LIMIT 2",ref.tenantId(),checkReceipt.required("event_id").asText(),text(check,"check_id")));same(checkReceipt,json.read(text(checkEvent,"payload")));
  var manifest=c.produced().artifacts().stream().filter(a->"ASSEMBLY_MANIFEST".equals(a.kind())).findFirst().orElseThrow();var manifestRow=one(db.queryForList("SELECT canonical_payload FROM task_candidate_assembly_object WHERE tenant_id=? AND artifact_id=? LIMIT 2 FOR UPDATE",ref.tenantId(),manifest.artifactId()));var checkIds=json.read(text(manifestRow,"canonical_payload")).required("check_ids");boolean present=false;for(var id:checkIds)if(text(check,"check_id").equals(id.asText()))present=true;if(!present)bad();
  proof.require(proof.operation());return result;
 }
 private void current(WorkflowProtocol.Reference ref,TaskCandidateAssemblyAuthority.Verified i)throws Exception{i.requireUnchanged();same(ref.tenantId(),i.production().tenantId());same(ref.projectId(),i.production().projectId());same(ref.runId(),i.production().runId());protocols.assemblies().requireAccepted(i.production().admission(),ref.runId()).requireUnchanged();}
 private JsonNode body(WorkflowProtocol.Reference ref,ProducedV1 produced)throws Exception{return json.tree(Map.of("schema_version","1.0.0","kind","TASK_N06_COMMIT","reference",ref,"produced",produced));}
 private Optional<JsonNode> read(EnterpriseAccess.Admission a,WorkflowProtocol.Reference ref,String operation,String action)throws Exception{var r=run(a,ref);return journal.read(a,ref.projectId(),ref.runId(),derived(action,operation),operation,operation+":"+ref.runId(),action,ref.inputSha256(),text(r,"classification"),"1.0.0",MANIFEST);}
 private Optional<JsonNode> read(EnterpriseAccess.Admission a,WorkflowProtocol.Reference ref,String operation,String action,TaskCandidateAssemblyHumanReadAuthority.Verified human)throws Exception{if(human==null)return read(a,ref,operation,action);human.require(a);same(ref.runId(),human.runId());same(ref.projectId(),human.projectId());var r=one(db.queryForList("SELECT classification FROM task_run WHERE tenant_id=? AND project_id=? AND run_id=? AND created_by=? LIMIT 2 FOR UPDATE",ref.tenantId(),ref.projectId(),ref.runId(),human.originalActorId()));return journal.readOriginalActor(a,human.originalActorId(),ref.projectId(),ref.runId(),derived(action,operation),operation,operation+":"+ref.runId(),action,ref.inputSha256(),text(r,"classification"),"1.0.0",MANIFEST);}
 private void write(EnterpriseAccess.Admission a,WorkflowProtocol.Reference ref,String operation,String action,JsonNode value)throws Exception{var old=read(a,ref,operation,action);if(old.isPresent()){same(old.get(),value);return;}journal.write(a,ref.projectId(),ref.runId(),derived(action,operation),operation,operation+":"+ref.runId(),action,ref.inputSha256(),text(run(a,ref),"classification"),"1.0.0",MANIFEST,value);}
 private Map<String,Object> run(EnterpriseAccess.Admission a,WorkflowProtocol.Reference ref){same(a.context().tenant_id(),ref.tenantId());return one(db.queryForList("SELECT * FROM task_run WHERE tenant_id=? AND project_id=? AND run_id=? AND created_by=? AND execution_kind='TASK' LIMIT 2 FOR UPDATE",ref.tenantId(),ref.projectId(),ref.runId(),a.actorId()));}
 private static String action(WorkflowProtocol.Reference ref){return TaskCandidateAssemblyAuthority.derived("ACTION",ref.runId());}
}
